<template>
  <div class="learning-view">
    <div class="container">
      <!-- ==================== 页面头部 ==================== -->
      <header class="page-header">
        <!-- 面包屑导航 -->
        <nav class="breadcrumb">
          <router-link to="/" class="breadcrumb-link">首页</router-link>
          <span class="breadcrumb-separator">/</span>
          <span class="breadcrumb-current">在线学习</span>
        </nav>
        <h1 class="page-title">在线学习</h1>
        <p class="page-desc">
          跟随非遗传承人学习传统技艺，感受千年文化的魅力
        </p>
      </header>

      <!-- ==================== 分类标签栏 ==================== -->
      <div class="category-tabs">
        <button
          v-for="cat in courseCategories"
          :key="cat"
          class="tab-btn"
          :class="{ active: currentCategory === cat }"
          @click="selectCategory(cat)"
        >
          {{ cat }}
        </button>
      </div>

      <!-- ==================== 结果统计 ==================== -->
      <div class="result-stats">
        共 <span class="stats-highlight">{{ totalCount }}</span> 门课程
        <span v-if="currentCategory !== '全部'" class="filter-tag">{{ currentCategory }}</span>
      </div>

      <!-- ==================== 内容区域 ==================== -->
      <!-- 加载状态: 骨架屏 -->
      <div v-if="loading && courses.length === 0" class="course-grid">
        <SkeletonLoader v-for="i in pageSize" :key="i" type="card" />
      </div>

      <!-- 空状态 -->
      <EmptyState
        v-else-if="!loading && courses.length === 0"
        title="暂无相关课程"
        description="该分类下暂时没有课程，请尝试其他分类"
        icon="&#x1F4DA;"
      />

      <!-- 数据展示: 课程卡片网格 -->
      <div v-else class="course-grid">
        <TransitionGroup name="card-fade">
          <CourseCard
            v-for="course in courses"
            :key="course.id"
            :data="course"
            class="course-card"
          />
        </TransitionGroup>
      </div>

      <!-- ==================== 分页组件 ==================== -->
      <div v-if="totalPages > 1" class="pagination">
        <!-- 上一页 -->
        <button
          class="page-btn"
          :disabled="currentPage === 1"
          @click="goToPage(currentPage - 1)"
        >
          <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="15 18 9 12 15 6"></polyline></svg>
        </button>

        <!-- 页码按钮 -->
        <template v-for="page in displayedPages" :key="page">
          <span v-if="page === '...'" class="page-ellipsis">...</span>
          <button
            v-else
            class="page-btn"
            :class="{ active: page === currentPage }"
            @click="goToPage(page)"
          >
            {{ page }}
          </button>
        </template>

        <!-- 下一页 -->
        <button
          class="page-btn"
          :disabled="currentPage === totalPages"
          @click="goToPage(currentPage + 1)"
        >
          <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="9 18 15 12 9 6"></polyline></svg>
        </button>

        <!-- 页码信息 -->
        <span class="page-info">第 {{ currentPage }} / {{ totalPages }} 页</span>
      </div>
    </div>
  </div>
</template>

<script setup>
/**
 * LearningView.vue - 在线学习页面
 *
 * 功能:
 * - 页面标题 + 面包屑 + 描述
 * - 分类标签栏 (可点击切换): 全部/汉绣/漆器/挑花/皮影/武术/民歌/戏曲/其他
 * - 响应式课程卡片网格 (4/3/2/1列)
 * - 分页组件
 * - 骨架屏 + 空状态处理
 */
import { ref, computed, onMounted } from 'vue'
import { useStore } from 'vuex'
import CourseCard from '@/components/CourseCard.vue'
import SkeletonLoader from '@/components/SkeletonLoader.vue'
import EmptyState from '@/components/EmptyState.vue'

// Store
const store = useStore()

// ==================== 课程分类 ====================
// 内置分类列表 (也可从store获取)
const courseCategories = ref([
  '全部', '汉绣', '漆器', '挑花', '皮影', '武术', '民歌', '戏曲', '其他'
])

// 当前选中的分类
const currentCategory = ref('全部')

// ==================== 分页状态 ====================
const currentPage = ref(1)
const pageSize = 12
const totalCount = computed(() => store.state.coursesTotal || 0)
const totalPages = computed(() => Math.ceil(totalCount.value / pageSize))

// ==================== 数据 ====================
const loading = computed(() => store.state.loading)
const courses = computed(() => store.state.courses)

// ==================== 计算属性 ====================

/**
 * 计算要显示的页码列表 (支持省略号)
 */
const displayedPages = computed(() => {
  const total = totalPages.value
  const current = currentPage.value
  const pages = []

  if (total <= 7) {
    for (let i = 1; i <= total; i++) pages.push(i)
  } else {
    pages.push(1)
    if (current > 3) pages.push('...')
    const start = Math.max(2, current - 1)
    const end = Math.min(total - 1, current + 1)
    for (let i = start; i <= end; i++) pages.push(i)
    if (current < total - 2) pages.push('...')
    pages.push(total)
  }

  return pages
})

// ==================== 方法 ====================

/**
 * 选择分类标签
 * @param {string} cat - 分类名称
 */
const selectCategory = (cat) => {
  if (cat === currentCategory.value) return
  currentCategory.value = cat
  currentPage.value = 1
  fetchData()
}

/**
 * 根据当前分类和页码获取课程数据
 */
const fetchData = async () => {
  const params = {
    page: currentPage.value,
    limit: pageSize
  }
  // 仅非"全部"时添加分类参数
  if (currentCategory.value !== '全部') {
    params.category = currentCategory.value
  }

  try {
    await store.dispatch('fetchCourses', params)
  } catch (err) {
    console.error('获取课程列表失败:', err)
  }
}

/**
 * 跳转到指定页码
 * @param {number} page - 目标页码
 */
const goToPage = (page) => {
  if (page < 1 || page > totalPages.value) return
  currentPage.value = page
  fetchData()
  window.scrollTo({ top: 0, behavior: 'smooth' })
}

// ==================== 生命周期 ====================
onMounted(async () => {
  // 获取课程分类列表 (如store中有)
  if (store.state.courseCategories && store.state.courseCategories.length > 0) {
    // 将"全部"作为第一个选项
    courseCategories.value = ['全部', ...store.state.courseCategories]
  }

  // 获取课程数据
  await fetchData()
})
</script>

